SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(4*10^9);tt:=Cputime();root:="work/deg10/continuation_20261030b/C81/";AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");load "work/deg10/continuation_20261030b/C81/deps/native_group_generators.m";
CQ:=SmallModularCurve(81);jraw:=jInvariant(CQ,81);wraw:=DefiningPolynomials(AtkinLehnerInvolution(CQ,81,81));CC:=ChangeRing(CQ,GF(2));assert IsNonsingular(CC) and Genus(CC) eq 4;RC:=CoordinateRing(Ambient(CC));jn:=RC!Numerator(jraw);jd:=RC!Denominator(jraw);ww:=[RC!v:v in wraw];FF:=FunctionField(CC);j0:=FF!(jn/jd);jw0:=FF!(Evaluate(jn,ww)/Evaluate(jd,ww));F0,mp:=AlgorithmicFunctionField(FF);F:=RationalExtensionRepresentation(F0);jj:=F!mp(j0);jw:=F!mp(jw0);assert Genus(F) eq 4;cs:=Poles(jj);assert &+[Degree(p)*(-Valuation(jj,p)):p in cs] eq 108;A:=Divisor([p:p in cs|Degree(p) eq 1][1]);
ivs:=ClassGroupAbelianInvariants(F:ReductionDivisor:=A,Proof:=true);assert F`cld`proven;MDProvenClassGroupGenerators(F);G:=F`cld`Cl;ff:=F`cld`ZnToCl;Z:=Domain(ff);fb:=Reverse([v`place:v in F`cld`fb]);fc:=[ff(Z.i):i in [1..#fb]];assert &*[v:v in Invariants(G)|v ne 0] eq 54;
function ER(v) return [[Integers()!a:a in Coefficients(Numerator(v))],[Integers()!a:a in Coefficients(Denominator(v))]];end function;
function EF(v) return [ER(c):c in Eltseq(F!v)];end function;
OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);pa,ea:=Support(F`cld`A1);assert #pa eq 1 and ea[1] eq 1;ai:=Index(fb,pa[1]);hg:=[2*G.i:i in [1..Ngens(G)-1]];H:=sub<G|hg>;assert #H eq 27;out:=[*[ER(v):v in Coefficients(DefiningPolynomial(F))],[Order(Ideal(p)) eq OF select 1 else 0:p in fb],[Degree(p):p in fb],[*[EF(v):v in Basis(Ideal(p))]:p in fb*],[Eltseq(v):v in fc],[Eltseq(v):v in Rows(RelationMatrix(G))],[EF(jj),EF(jw)],ai,[Eltseq(v):v in hg],[[*Degree(p),Order(Ideal(p)) eq OF select 1 else 0,[EF(v):v in Basis(Ideal(p))]*]:p in cs]*];Write(root cat "x0_81_proven_picard.m",Sprint(out):Overwrite:=true);print "C81_X0_PROVEN_PICARD_COMPLETE",Degree(F),Invariants(G),Invariants(H),#fb,[Degree(p):p in cs],Cputime(tt);quit;
